package com.example

import com.example.ExamQuestionHelper.QSpec

object DancingLiveExamShanthikarmaBank1 {
    private const val T = "දේශීය ශාන්තිකර්ම හා යාතුකර්ම"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("දේශීය 'ශාන්තිකර්මයක්' පැවැත්වීමේ ප්‍රධානතම අරමුණ කුමක්ද?", "රෝග බිය, අපල හා උවදුරු දුරු කර සෙත් ශාන්තිය උදා කර ගැනීම", "හුදෙක් ප්‍රේක්ෂක විනෝදාස්වාදය උදෙසා තරග පැවැත්වීම", "රාජ සභා නඩු විභාග හා රාජකීය පනත් ප්‍රකාශයට පත් කිරීම", "ගැමි කෘෂිකාර්මික ශ්‍රම හුවමාරු කටයුතු සංවිධානය කිරීම", "ශාන්ති හෙවත් යහපත උදා කර ගැනීම සඳහා දෙවියන්, ග්‍රහයන් හා යකුන් පිදීම සිදු කෙරේ."),
        q("ශ්‍රී ලංකාවේ ශාන්තිකර්ම ප්‍රධාන කොටස් තුනකට බෙදා දක්වනු ලැබේ. ඒවා මොනවාද?", "දේව ශාන්තිකර්ම, ග්‍රහ ශාන්තිකර්ම සහ යක්ෂ ශාන්තිකර්ම", "වන්නම්, සරඹ සහ කස්තිරම්", "රබන්, කළගෙඩි සහ ලී කෙළි", "භරත, කථක් සහ ඔඩිසි", "පිදුම් ලබන අදෘශ්‍යමාන බලවේගය අනුව මෙම ත්‍රිවිධ වර්ගීකරණය සිදු කර ඇත."),
        q("උඩරට සම්ප්‍රදායේ ප්‍රධානතම 'දේව ශාන්තිකර්මය' කුමක්ද?", "කොහොඹා කංකාරිය", "දහඅට සන්නිය", "මහ සොහොන් සමයම", "රට යකුම", "කොහොඹා දෙවියන් ප්‍රමුඛ දොළොස් දෙවිවරුන් උදෙසා උඩරට කොහොඹා කංකාරිය පවත්වයි."),
        q("පහතරට සම්ප්‍රදායේ ප්‍රධානතම 'දේව ශාන්තිකර්මය' ලෙස සැලකෙන්නේ කුමක්ද?", "දෙවොල් මඩුව හෙවත් ගම්මඩුව", "වලියක් මංගල්‍යය", "බලි යාගය", "පඬුවස්දෙව් කංකාරිය", "පත්තිනි මෑණියන් හා දෙවොල් දෙවියන් උදෙසා පවත්වන පහතරට මහා ශාන්තිකර්මය මෙයයි."),
        q("සබරගමු සම්ප්‍රදායේ ප්‍රධානතම 'දේව ශාන්තිකර්මය' කුමක්ද?", "පහන් මඩුව", "දහඅට සන්නිය", "හූනියම් කැපිල්ල", "සොකරි නාටකය", "සුමන සමන් දෙවියන් හා පත්තිනි දේවිය මුල් කර ගනිමින් සබරගමු පහන් මඩුව පැවැත්වේ."),
        q("නව ග්‍රහයන්ගෙන් ඇතිවන අපල උපද්‍රව දුරු කිරීම සඳහා පවත්වන 'ග්‍රහ ශාන්තිකර්මය' කුමක්ද?", "බලි යාගය හෙවත් බලි ශාන්තිකර්මය", "දෙවොල් මඩුව", "ගරා යකුම", "රට යකුම", "මැටි සහ රෙදිවලින් නව ග්‍රහ රූප අඹා සිත්තම් කරමින් බලි ශාන්තිකර්මය පවත්වයි."),
        q("ගැබිනි මව්වරුන්ගේ දරු ප්‍රසූතිය සුවදායක වීම හා ආරක්ෂාව පතා පවත්වන පහතරට යක්ෂ ශාන්තිකර්මය කුමක්ද?", "රට යකුම හෙවත් රිද්දි යාගය", "කොහොඹා කංකාරිය", "පහන් මඩුව", "මහ සොහොන් සමයම", "කළු යකා හා රිද්දි බිසවුන් හත්දෙනාගේ පුවත රට යකුමේදී රඟ දැක්වේ."),
        q("සතුරු වින දෝෂ හා අණවින කොඩිවින කපා ඉවත් කිරීම සඳහා පවත්වන ප්‍රධාන පහතරට යාගය කුමක්ද?", "සූනියම් කැපිල්ල හෙවත් ශූනියම් යාගය", "බලි යාගය", "ගොයම් නැටුම", "කළගෙඩි නැටුම", "වඩිග පටුන රංගනය හා පුහුල් කැපීම සූනියම් යාගයේ ප්‍රධාන අංග වේ."),
        q("රෝග දහඅටක් සමනය කිරීම අරමුණු කරගෙන පවත්වන පහතරට යක්ෂ ශාන්තිකර්මය කුමක්ද?", "දහඅට සන්නිය", "කොහොඹා කංකාරිය", "බලි යාගය", "පහන් මඩුව", "මහ කෝල සන්නි යකා ඇතුළු සන්නි 18 ක් මෙම ශාන්තිකර්මයේදී නැටවේ."),
        q("මහනුවර ඇසළ පෙරහැර අවසන් වූ පසු දළදා මාලිගාවට හා සිව් මහා දේවාලවලට සෙත් පතා පවත්වන ශාන්තිකර්මය කුමක්ද?", "වලියක් මංගල්‍යය", "දහඅට සන්නිය", "රට යකුම", "පූනා මඩුව", "පෙරහැර කටයුතුවලදී ඇති වූ ඇස්වහ කටවහ දෝෂ දුරු කිරීමට විෂ්ණු දේවාලයේ මෙය දින හතක් පවත්වයි."),
        q("කොහොඹා කංකාරියේ පුරාවෘත්තයට අනුව දිවි දෝෂය වැළඳුණු ශ්‍රී ලංකාවේ පැරණි රජතුමා කවුද?", "පඬුවස්දෙව් රජතුමා", "විජය රජතුමා", "දුටුගැමුණු රජතුමා", "පරාක්‍රමබාහු රජතුමා", "කුවේණියගේ ශාපය නිසා පඬුවස්දෙව් රජුට ඇති වූ දිවි දෝෂය සුව කිරීමට කංකාරිය ආරම්භ විය."),
        q("කොහොඹා කංකාරිය පැවැත්වීමේදී ශාන්තිකර්ම මඩුව මැද ඉදිකරන ප්‍රධාන පූජා ආසනය හඳුන්වන්නේ කුමන නමකින්ද?", "අයිලය හෙවත් යක්කම් පහේ ආසනය", "බලි තටුව", "කඩතුරාව", "හිඳි කුටිය", "කොහොඹා දෙවියන් ඇතුළු දේව ආභරණ තැන්පත් කරන පූජනීය මැස්ස අයිලය නම් වේ."),
        q("ශාන්තිකර්ම මඩුවට ආරාධනා කර ගැනීමට පෙර බුලත්, පුවක් හා මල් තබා සූදානම් කරන මූලික පූජා වට්ටිය කුමක්ද?", "මල් බුලත් තටුව", "බලි පුවරුව", "යක් තටුව", "කැවිලි පෙට්ටිය", "සෑම දේශීය ශාන්තිකර්මයකම ආරම්භයේදී මල් බුලත් තටුව සකස් කර සාක්ෂි තබයි."),
        q("ශාන්තිකර්මයකදී ආතුරයා (රෝගියා) වෙත දෝෂ ඇද ගැනීම හා පිරිසිදු කිරීම සඳහා අතට දෙන සුදු නූල කුමක්ද?", "කන්‍යා නූල (ඇප නූල)", "වරපටි නූල", "කඹය", "රබර් පටිය", "අවසානයේ පිරිත් කර ගැටගසන ඇප නූල ආතුරයාට මානසික ආරක්ෂාවක් ගෙන දෙයි."),
        q("බලි ශාන්තිකර්මයේදී බලි රූප ඇඹීම සඳහා යොදා ගන්නා ප්‍රධාන ස්වාභාවික මාධ්‍යය කුමක්ද?", "හුඹස් මැටි, කෙසෙල් පතුරු සහ ඛනිජ වර්ණක", "සිමෙන්ති සහ යකඩ", "ප්ලාස්ටික් සහ වීදුරු", "ඇලුමිනියම් තහඩු", "තාවකාලික පූජා කලාවක් වන බලි රූප පරිසර හිතකාමී මැටිවලින් අඹනු ලැබේ."),
        q("ශාන්තිකර්මයකදී 'කඩතුරාව' ඉවත් කිරීම යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "දේව හෝ යක්ෂ රංගනය ඉදිරියට පැමිණීමේදී ආවරණ රෙද්ද ඉවත් කිරීම", "යාග මඩුවේ ඉහළ වියන හා වහලය ගලවා ඉවත් කිරීම", "මඩුවේ සියලු බෙර වාදන අංග සම්පූර්ණයෙන් නතර කිරීම", "රංගනය ආරම්භ වීමට පෙර ප්‍රේක්ෂකයන් පිටතට යැවීම", "නාට්‍යමය කුතුහලය හා පූජනීය බව රැකීමට සුදු හෝ රතු කඩතුරාව භාවිත කෙරේ."),
        q("සෑම දේශීය ශාන්තිකර්මයකම පාහේ අවසානයේදී ඇස්වහ කටවහ දෝෂ දුරු කිරීමට නටන ප්‍රධාන අංගය කුමක්ද?", "ගරා යකුම (ගරා නැටුම)", "සොකරි නැටුම", "ගජගා වන්නම", "ලී කෙළි නැටුම", "සමස්ත ශාන්තිකර්මයේම අඩුපාඩු නිවැරදි කර ආශිර්වාද ගෙන ඒමට ගරා යකා නටවයි."),
        q("ශාන්තිකර්ම අතර 'දුම්මල ගැසීම' මඟින් ඉටු වන ප්‍රධාන කාර්යය කුමක්ද?", "අලංකාර ගිනි සිළු මැවීම, විෂබීජ නාශනය හා සුවඳ දුම් ඇල්ලීම", "යාග මඩුවේ දැල්වෙන සියලු පහන් නිවා මඩුව අඳුරු කිරීම", "වර්ෂාව ඇති වීම වැළැක්වීම සඳහා පූජා විධි නතර කිරීම", "වාද්‍ය භාණ්ඩවල සම් මතුපිට ගිනි දැල්ලට අල්ලා පිළිස්සීම", "දුම්මල කුඩු පන්දමට ගැසීමෙන් ගිනි ජාලාවක් මැවී ආතුරයා තුළ විශ්වාසය ඇති වේ."),
        q("කොහොඹා කංකාරියේදී ඉදිරිපත් කරන ප්‍රධාන නාට්‍යමය හාස්‍ය අංගයක් කුමක්ද?", "වැදි යක්කම හා ඌරු යක්කම", "ජසයා හා ලෙන්චිනා", "මනමේ කුමරු", "ගුරුහාමි සහ සොකරි", "කොහොඹා කංකාරිය තුළ යක්කම් පහ නමින් ප්‍රසිද්ධ නාට්‍යමය අංග පහක් පවතී."),
        q("පහතරට 'මහ සොහොන් සමයම' පැවැත්වෙන්නේ කුමන ආකාරයේ රෝග හා බිය තත්ත්වයන් සමනය කිරීමටද?", "තදබල බිය, තැතිගැන්ම හා අමනුෂ්‍ය දෝෂ", "සරු අස්වැන්නක් සඳහා වූ කමත් වී පූජා", "දරු ප්‍රසූතිය හා මාතෘ ආරක්ෂක පිළිවෙත්", "නව ග්‍රහ දශා මාරුවීමේ ජ්‍යොතිෂ්‍ය පූජා", "භයානක වෙස් ගත් මහ සොහොන් නැටුම රෝගියාගේ බිය පහ කිරීමට සිදු කරන මනෝ චිකිත්සාවකි."),
        q("දේශීය ශාන්තිකර්මවල 'ආතුරයා' යන පදයෙන් හඳුන්වනු ලබන්නේ කවුරුන්ද?", "ශාන්තිකර්මයෙන් සුවය හා ආශිර්වාදය අපේක්ෂා කරන ප්‍රධාන පුද්ගලයා", "යාග මඩුවේ ප්‍රධාන ගැටබෙර හෝ යක් බෙර වාදකයා", "දහඅට සන්නි රංගනය සඳහා ලී වෙස්මුහුණු කපන ශිල්පියා", "ගොක් කොළ කැටයම් හා පූජා මඩුව නිමවන වඩු ශිල්පියා", "රෝගියා හෝ යාගයේ අයිතිකරු ආතුරයා නමින් හඳුන්වනු ලැබේ."),
        q("දේශීය ශාන්තිකර්ම ඉදිරිපත් කරන ප්‍රධාන කලාකරුවා හෙවත් යාගාචාර්යවරයා හඳුන්වන්නේ කුමන නමකින්ද?", "යකැදුරුතුමා, කපු මහතා හෝ බලි ඇදුරා", "නාඩගම් පොතේගුරු හා සංගීත අධ්‍යක්ෂ", "කෝලම් රංගනයේ විකට දෙබස් කියන්නා", "වෙස් නැටුමේ ආධුනික හේවිසි හා හොරණෑ වාදකයා", "දේව ශාන්තිකර්ම කපු මහතුන්ද ග්‍රහ ශාන්තිකර්ම බලි ඇදුරන්ද මෙහෙයවති."),
        q("සබරගමු 'පහන් මඩුව' හා පහතරට 'ගම්මඩුව' අතර ඇති ප්‍රධාන සමානකම කුමක්ද?", "දෙකම ගමටම පොදුවේ සෙත් පතා දෙවියන් උදෙසා පැවැත්වෙන දේව ශාන්තිකර්ම වීම", "දෙකෙහිම උඩරට සම්ප්‍රදායේ එකම ගැටබෙරය පමණක් ප්‍රධානව වැයීම", "දෙකම බටහිර සම්භාව්‍ය සංගීත භාණ්ඩ ඇසුරෙන් රඟ දක්වනු ලැබීම", "දෙකම නිවසක එක් රෝගියෙකු උදෙසා පමණක් පෞද්ගලිකව සීමා වීම", "මහජන සුභසිද්ධිය හා කෘෂිකාර්මික සෞභාග්‍යය පැතීම මෙම මඩු යාගවල පොදු අරමුණයි."),
        q("බලි ශාන්තිකර්මයේදී ආතුරයාගේ හිස මත තබා ආශිර්වාද කරන මල් හා කොළ අතු කළඹ හඳුන්වන්නේ කෙසේද?", "ඉහළ මල් හෝ ඉස් මුදුන් දළුමුරය (හිස තැබීමේ පිළිවෙත)", "දහඅට සන්නියේ සන්නි පොල්ල හා මුහුණු පෙළ", "උඩරට පා සරඹ පුහුණු වන දණ්ඩියම් කඳ", "තම්මැට්ටම් වාදනය සඳහා ගන්නා කඩිප්පු යුගලය", "ආතුරයාගේ හිස සිට දෙපතුල දක්වා දෝෂ ඉවත් කිරීමේ ආශිර්වාද කවි කියමින් මෙය සිදු කරයි."),
        q("කොහොඹා කංකාරියේදී 'මලය රජු' ලක්දිවට ගෙන්වා ගැනීම සඳහා රාහු අසුරයා ගත් වෙස් ස්වරූපය කුමක්ද?", "මහා ඌරෙකුගේ (සූකර) වෙසක්", "මොනරෙකුගේ වෙසක්", "කිරලෙකුගේ වෙසක්", "හාවෙකුගේ වෙසක්", "මලය රජුගේ උයන වැනසූ මායා ඌරා පසුපස ලුහුබැඳ මලය රජු ලක්දිවට පැමිණි බව කියැවේ."),
        q("කොහොඹා කංකාරියේ 'යක් තුන්පදේ' හෝ 'මඟුල් බෙර' වාදනයෙන් පසු ගායනා කරන පැරණි ප්‍රශස්ති අංගය කුමක්ද?", "යක් ඇනුම", "සළු පාලිය", "වඩිග පටුන", "කෝලම් රංගනය", "යකුන්ට හා දෙවියන්ට ආරාධනා කරන ගාම්භීර පූජා නැටුමක් ලෙස යක් ඇනුම සැලකේ."),
        q("දේශීය ශාන්තිකර්මයක 'තොරණ' හෙවත් 'වීදිය' සැරසීමේදී බහුලව භාවිත කරන පාරිසරික ද්‍රව්‍යය කුමක්ද?", "ළපටි පොල් කොළ හෙවත් ගොක් කොළ", "වර්ණවත් ප්ලාස්ටික් බෑග්", "රබර් ටයර්", "යකඩ තහඩු", "ගොක් කොළ කලාව ශ්‍රී ලාංකේය ශාන්තිකර්ම මණ්ඩපයේ සෞන්දර්ය අනන්‍යතාවයි."),
        q("ශාන්තිකර්ම පූජාවන්හිදී 'පහන් දැල්වීම' සඳහා සාම්ප්‍රදායිකව භාවිත කරන තෙල් වර්ගය කුමක්ද?", "පිරිසිදු පොල් තෙල් හෝ තල තෙල්", "මැටි වතුර", "පැණි සහ කිරි", "ගස් කොළ යුෂ", "පූජනීයත්වය හා පවිත්‍රතාව රැකීමට ස්වාභාවික පොල් තෙල් පහන් දල්වයි."),
        q("පහතරට 'රට යකුම' ශාන්තිකර්මයේ ප්‍රධාන කොටසක් වන 'නානුමුර' හා 'කපු කැටීම' නිරූපණය කරන්නේ කවුරුන් විසින්ද?", "රිද්දි බිසවුන් හත්දෙනා විසින්", "සන්නි යකුන් දහඅට දෙනා විසින්", "හේවා රාළලා විසින්", "ගුරුහාමි විසින්", "කපු නෙළා, නූල් කටා සළු වියා බුදුන්ට හා දෙවියන්ට පූජා කිරීමේ කතා පුවත මෙහි රඟ දැක්වේ."),
        q("ශාන්තිකර්මයකදී 'පිදේනි තටුව' සාදා එය යාගය අවසානයේ පිටතට ගෙන ගොස් තබන්නේ ඇයි?", "යකුන් හා අමනුෂ්‍ය දෝෂ සතුටු කර ආතුරයාගෙන් ඉවතට පිටත් කිරීමට", "අමුත්තන්ට රාත්‍රී ආහාර දීමට", "වේදිකාව සේදීමට", "බෙර වාදකයාට තෑගි දීමට", "තටු හා පිදේනි ඔප්පු කිරීම යක්ෂ ශාන්තිකර්මවල ප්‍රධාන චාරිත්‍රයකි."),
        q("සබරගමු 'පහන් මඩුව' තුළදී 'ගින්න' ආශ්‍රිතව සිදු කරන ප්‍රධාන ආශිර්වාදාත්මක අංගය කුමක්ද?", "ගිනි මැලය වටා නැටීම හා ගිනි පෑගීම", "ගින්නෙන් පැරණි පුස්කොළ පොත් පිළිස්සීම", "පූජා බෙර ගිනි මැලය අසලින් ඉවතට ගැනීම", "මඩුවේ සියලු මැටි පහන් එකවර නිවා දැමීම", "සත්පත්තිනි දේව බලය ප්‍රදර්ශනය කරමින් ආශිර්වාද කිරීම මෙහිදී සිදු වේ."),
        q("බලි යාගයකදී යොදා ගන්නා 'කවි මාලාව' හඳුන්වනු ලබන්නේ කුමන නමකින්ද?", "ග්‍රහ ස්තෝත්‍ර හා බලි කවි", "ලී කෙළි කවි", "ගොයම් කවි", "කළගෙඩි කවි", "සූර්ය, චන්ද්‍ර, අඟහරු ආදී ග්‍රහයන්ගේ ගුණ වර්ණනා කරමින් බලි කවි ගැයේ."),
        q("දේශීය ශාන්තිකර්ම කලාවෙන් වත්මන් සමාජයට ලැබෙන ප්‍රධානම මානසික හා සමාජීය ප්‍රතිලාභය කුමක්ද?", "රෝගියාට මානසික සහනයක් ලැබීම හා ගැමි එකමුතුව තහවුරු වීම", "සාම්ප්‍රදායික ගැමි වෙදකම මුළුමනින්ම ඉවත දැමීම", "ගමේ පවුල් අතර සමාජ භේද හා අමනාපකම් ඇති වීම", "දේශීය බෙර වාදන හා කවි සාහිත්‍යය අමතක වී යාම", "මනෝ චිකිත්සක ගුණය හා සාමූහික සහභාගීත්වය ශාන්තිකර්මයේ වටිනාකමයි."),
        q("කොහොඹා කංකාරියේදී 'ගුරුගෙදර' හෝ 'මඩුව' පිරිසිදු කිරීම සඳහා පළමුව සිදු කරන චාරිත්‍රය කුමක්ද?", "මඩු පේ කිරීම හෙවත් කප් සිටුවීම", "බෙර ගලවා දැමීම", "ප්‍රේක්ෂකයන් පිට කිරීම", "වෙස් තට්ටු සේදීම", "ශුභ නැකතින් කප් සිටුවා යාග මඩුව ගොඩනැගීම පළමු චාරිත්‍රයයි."),
        q("පහතරට 'සූනියම් යාගයේ' අවසානයේදී ආතුරයා ඉදිරියේ අළු පුහුල් ගෙඩියක් කපා දමන්නේ කුමක් සංකේතවත් කිරීමටද?", "සියලු අණවින හා දෝෂ සම්පූර්ණයෙන් කපා ඉවත් කළ බව", "මඩු පූජාව අවසානයේ දේව දානය පිසීම ආරම්භ කිරීමට", "ශාන්තිකර්මය නියමිත පරිදි අවසන් කළ නොහැකි බව දැන්වීමට", "ගැමි කෘෂිකාර්මික අස්වැන්නේ වර්ධනය ප්‍රදර්ශනය කිරීමට", "පුහුල් ගෙඩිය දෙකට කැපීමත් සමඟ රෝගියාගේ සිතේ පවතින බිය පහව යයි."),
        q("උඩරට 'වලියක් මංගල්‍යය' පවත්වනු ලබන්නේ කුමන දේවාල පරිශ්‍රයකදීද?", "මහනුවර මහා විෂ්ණු දේවාලයේදී", "අම්බලන්ගොඩ කෝලම් මඩුවේදී", "රත්නපුර මහ සමන් දේවාලයේදී", "කතරගම මුහුදු වෙරළේදී", "ඇසළ පෙරහැර අවසානයේ විෂ්ණු දේවාලයේදී වෙස් නොවන ගැරහුම් ඇඳුමින් මෙය නටයි."),
        q("ශාන්තිකර්මයකදී 'කුකුළු පාලිය' හෝ 'හුළු පාලිය' ඉදිරිපත් කිරීමේදී යොදා ගන්නා ආලෝක උපකරණය කුමක්ද?", "හුළු අතු හෙවත් පන්දම්", "පිත්තල තාලම්පට", "මැටි කළගෙඩි", "ඉටිපන්දම් පෙට්ටි", "රාත්‍රී ශාන්තිකර්මවල ආලෝකය හා රිද්මය මැවීමට පන්දම් භාවිත කෙරේ."),
        q("දේශීය ශාන්තිකර්ම හා ජන නාට්‍ය අතර ඇති සම්බන්ධතාව කුමක්ද?", "සන්නි හා යක්කම් වැනි අංග තුළින් දේශීය නාට්‍ය කලාවේ බීජ හටගැනීම", "ශාන්තිකර්ම නිසා නාට්‍ය තහනම් වීම", "කිසිදු සම්බන්ධයක් නොමැති වීම", "දෙකම විදේශයෙන් ආනයනය කිරීම", "ශාන්තිකර්ම පෙළපාලිවල දෙබස්, වෙස් ගැන්වීම් හා රංගනය නාට්‍ය කලාවට මුල් විය."),
        q("බලි යාගයේදී නව ග්‍රහයන් සංකේතවත් කිරීමට බලි රූපවල භාවිත කරන වර්ණ පහ මොනවාද?", "රතු, කහ, සුදු, කළු සහ නිල් (පංච වර්ණ)", "කොළ සහ අළු පමණි", "රන් හා රිදී පමණි", "දුඹුරු පමණි", "ස්වාභාවික මකුළු මැටි හා ගස් පොතු ආදියෙන් මෙම පංච වර්ණ සකසා ගනී."),
        q("ශාන්තිකර්මයක 'ආරක්ෂාව' සඳහා ආතුරයා වටා ඉරි ගැසීම හෝ නූල් ඇදීම හඳුන්වන්නේ කෙසේද?", "සීමා බන්ධනය හෙවත් කඩවර පාලනය", "මණ්ඩිය නැවීම", "කස්තිරම නැටීම", "වන්නම ගැයීම", "අමනුෂ්‍ය දෝෂ ඇතුළු නොවන සේ මඩුව හා ආතුරයා ආරක්ෂා කිරීම සීමා බැඳීමයි."),
        q("පහතරට 'දෙවොල් මඩුවේ' ප්‍රධාන කථා වස්තුවට සම්බන්ධ 'දෙවොල් දෙවියන්' ලංකාවට ගොඩ බැස්සේ කුමන ප්‍රදේශයකින්ද?", "දකුණු ලක සීනිගම හා වැලිගම වෙරළ තීරයෙන්", "යාපනය පේදුරු තුඩුවෙන්", "ත්‍රිකුණාමලය වරායෙන්", "මීගමුව කලපුවෙන්", "මුහුදු බත් වූ නැව් හතක පුවත සමඟ දෙවොල් දෙවියන් ලංකාවට පැමිණි බව කියැවේ."),
        q("කොහොඹා කංකාරියේදී නැට්ටුවන් අතේ තබා ගන්නා 'කඩුව' සහ 'පලිහ' වෙනුවට යොදාගන්නා පූජා ආයුධ මොනවාද?", "දෙවියන්ගේ රන් ආයුධ හා සළඹ", "ලී කෙළි", "වේවැල් කුලු", "මැටි කළ", "කොහොඹා දෙවියන්ගේ හා මලය රජුගේ ආයුධ සංකේත පූජා ආසනයේ තබයි."),
        q("ශාන්තිකර්මයකදී 'සභා ආශිර්වාදය' හෙවත් 'පින් අනුමෝදනාව' සිදු කරන්නේ කුමන අවස්ථාවේදීද?", "ශාන්තිකර්මයේ අවසාන භාගයේදී", "මඩුව සෑදීමටත් පෙර", "බෙරය මිලදී ගන්නා දිනයේදී", "මැද රාත්‍රියේ නින්දට පෙර", "සියලු දෙවියන්ට හා රැස්වූ පිරිසට පින් දී සෙත් පතමින් යාගය නිම කරයි."),
        q("දේශීය ශාන්තිකර්ම සාහිත්‍යය අනුව 'පංච තූර්ය නාදය' ශාන්තිකර්මයට අත්‍යවශ්‍ය වන්නේ ඇයි?", "දෙවියන් පිදීමට හා යාගයේ රිද්මයානුකූල ගාම්භීර බව ඇති කිරීමට", "නැට්ටුවන්ගේ අත්පුඩි ගැසීම සම්පූර්ණයෙන් වැළැක්වීමට", "මඩුවට පැමිණි ආතුරයා හා පිරිස බිය ගැන්වීමට පමණක්", "පූජාවට ගෙන ආ සළු පිළි ඉක්මනින් වියළා ගැනීමට", "ශබ්ද පූජාව දේශීය යාතුකර්මවල අත්‍යවශ්‍ය අංගයකි."),
        q("සබරගමු 'මඩු ශාන්තිකර්මයේදී' සමන් දෙවියන් හැරුණු විට පිදුම් ලබන අනෙක් ප්‍රධාන දෙවියා කවුද?", "පත්තිනි දේවිය හා කතරගම දෙවියන්", "රෝම අපොලෝ දෙවියන්", "ග්‍රීක ඇතීනා දේවිය", "නෝර්ස් ඕඩින් දෙවියන්", "සමන්, පත්තිනි, කතරගම හා විෂ්ණු දෙවිවරු දේශීය ශාන්තිකර්මවල ප්‍රමුඛ වේ."),
        q("දේශීය ශාන්තිකර්මයකදී 'මල් බුලත් තටුව' සැකසීම සඳහා ගන්නා ප්‍රධාන පූජා ද්‍රව්‍යයක් කුමක්ද?", "පිරිසිදු බුලත් කොළ, පුවක් සහ සුදු මල්", "යකඩ ඇණ සහ කම්බි", "රබර් කැබලි", "ප්ලාස්ටික් පත්‍ර", "ශාන්තිකර්මයක සාක්ෂි තැබීම හා ආරාධනාව සඳහා මල් බුලත් තටුව භාවිත කෙරේ."),
        q("උඩරට 'කොහොඹා කංකාරිය' පැවැත්වීමේදී භාවිත කරන ප්‍රධාන වාද්‍ය භාණ්ඩය කුමක්ද?", "ගැටබෙරය", "පහතරට යක් බෙරය", "සබරගමු දිගු දවුල", "තබ්ලාව", "උඩරට ප්‍රධාන දේව ශාන්තිකර්මය ගැටබෙර නාදයෙන් මෙහෙයවනු ලැබේ."),
        q("පහතරට 'දහඅට සන්නිය' ඉදිරිපත් කිරීමේදී යකැදුරා සන්නි චරිත නිරූපණය කරන්නේ කුමක් පැළඳගෙනද?", "එක් එක් රෝගයට ආවේණික වූ වර්ණවත් ලී වෙස්මුහුණු", "උඩරට රිදී වෙස් තට්ටුව", "සබරගමු සුදු ජටාව", "ලෝහ හිස් ආවරණ", "සන්නි වෙස්මුහුණු පිළිබිඹු කරන රෝග ලක්ෂණ අනුව රංගනය හාස්‍ය හා චිකිත්සාව මුසු කරයි."),
        q("බලි ශාන්තිකර්මයේදී ග්‍රහ අපල දුරු කිරීමට බලි රූප ඉදිරියේ ආතුරයා හිඳුවා තබන්නේ කුමන දිශාවට මුහුණලාද?", "අපලයට අදාළ ග්‍රහ දිශාවට හා බලි රූපය දෙසට", "බිත්තිය දෙසට පමණක්", "අඳුරු මුල්ලක් දෙසට", "පිටුපසින් ඉවතට", "නිශ්චිත නැකැත් හා දිශා නියමයන්ට අනුව ආතුරයා ස්ථානගත කෙරේ."),
        q("පහතරට 'දෙවොල් මඩුවේදී' රාත්‍රී කාලයේ ගින්න සමඟ සිදු කරන ප්‍රධාන භක්ති පූජාව කුමක්ද?", "ගිනි පෑගීම සහ ගිනි මැලය වටා නැටීම", "වතුර ඉස පහන් නිවීම", "බෙර වාදනය නතර කිරීම", "පැදුරක නිදා ගැනීම", "දෙවොල් දෙවියන්ගේ හා පත්තිනි දේවියගේ ආශිර්වාදය මින් සංකේතවත් කෙරේ."),
        q("රට යකුම හෙවත් රිද්දි යාගයේදී 'පිරිසිදු නානු ගෑම' හෙවත් නානුමුර චාරිත්‍රය රඟ දක්වන්නේ ඇයි?", "මව්වරුන්ගේ හා දරුවන්ගේ පවිත්‍රතාව හා නිරෝගී බව සංකේතවත් කිරීමට", "ගමේ ළිඳ අසල සාමාන්‍ය ඇඳුම් සේදීමේ කටයුත්ත පෙන්වීමට", "දහඅට සන්නියේ ලී වෙස්මුහුණු කපා සායම් ආලේප කිරීමට", "මුළු ශාන්තිකර්ම නැටුම අතරමග නවතා අවසන් කිරීමට", "ගර්භණී කාන්තාවන්ට මානසික සහනය හා ආරක්ෂාව ගෙන දීම රට යකුමේ අරමුණයි."),
        q("කොහොඹා කංකාරියේදී 'මලය රජු' ලක්දිවට වැඩම කළ පසු දිවි දෝෂය සුව කළ රජතුමා කවුද?", "පඬුවස්දෙව් රජතුමා", "දේවානම්පියතිස්ස රජතුමා", "ධාතුසේන රජතුමා", "කීර්ති ශ්‍රී රාජසිංහ රජතුමා", "කුවේණියගේ ශාපය නිසා හටගත් දිවි දෝෂය පඬුවස්දෙව් රජුට වැළඳුණු බව පුරාවෘත්තයේ එයි."),
        q("ශාන්තිකර්මයකදී 'පහන් පැල' ඉදි කිරීමේදී යොදා ගන්නා ගොක් කොළ කලාවේ ප්‍රධාන අරමුණ කුමක්ද?", "මණ්ඩපයට පවිත්‍ර, සෞන්දර්යාත්මක හා පූජනීය පරිසරයක් මැවීම", "මඩුව තුළට පැමිණෙන වන සතුන් පලවා හැර බිය ගැන්වීම", "ශාන්තිකර්ම මණ්ඩපයේ වහලය සම්පූර්ණයෙන් අඳුරු කිරීම", "උත්සව සැරසිලි සඳහා වැය වන මුදල් අඩු කර ගැනීම පමණි", "ස්වාභාවික ශාක කොටස් යොදා සකසන ගොක් කොළ නිර්මාණ ශාන්තිකර්මයේ අනන්‍යතාවයි."),
        q("දේශීය ශාන්තිකර්ම අතරින් 'කිරි මඩුව' හෝ 'පූනා මඩුව' පවත්වනු ලබන්නේ කුමන ප්‍රධාන අරමුණකින්ද?", "ගව සම්පත ආරක්ෂා කිරීම සහ කෘෂිකාර්මික සෞභාග්‍යය පැතීම", "වෙස්මුහුණු ප්‍රදර්ශනය කිරීම", "රාජ සභාව රැස් කිරීම", "පාසල් ක්‍රීඩා තරග පැවැත්වීම", "ගැමි ආර්ථිකය හා බැඳුණු ගවයන්ගේ නිරෝගී බව පතා ගම්මුන් මේවා පවත්වති."),
        q("සූනියම් කැපිල්ල ශාන්තිකර්මයේදී 'වඩිග පටුන' රංගනය ඉදිරිපත් කරන චරිත කවුද?", "වඩිග දේශයෙන් පැමිණි බමුණන්ගේ චරිත", "සිංහල රජවරුන්ගේ චරිත", "වැදි නායකයන්ගේ චරිත", "විදේශීය නාවිකයන්ගේ චරිත", "බමුණු ඇඳුමින් සැරසී මන්ත්‍ර හා තාල වාදන සමඟ මෙම නාට්‍යමය අංගය රඟ දැක්වේ."),
        q("ශාන්තිකර්මයකදී 'ගරා යකුම' පැවැත්වීමෙන් බලාපොරොත්තු වන ප්‍රධාන සෙත් ශාන්තිය කුමක්ද?", "සියලු ඇස්වහ, කටවහ සහ හෝවහ දෝෂ දුරු කිරීම", "වර්ෂාව වැළැක්වීම", "රෝග වැඩි කිරීම", "මඩුව අඳුරු කිරීම", "කිසිදු ශාන්තිකර්මයක් ගරා යකා නැටවීමෙන් තොරව සම්පූර්ණ නොවන බව විශ්වාස කෙරේ."),
        q("බලි යාගයේදී 'බලි ඇදුරා' අතේ තබාගෙන සොලවන පිත්තල සීනුව හඳුන්වන්නේ කුමන නමකින්ද?", "අත් මිණිය හෙවත් මිණි ගෙඩිය", "පන්තේරුව", "තාලම්පට", "හක්ගෙඩිය", "බලි කවි ගායනා කරන විට මිහිරි නාදයක් ලබා ගැනීමට මිණි ගෙඩිය භාවිත කරයි."),
        q("පහතරට 'මහ සොහොන් සමයම' ආරම්භයේදී යකැදුරා සැරසී සිටින වෙස් ස්වරූපය කෙබඳුද?", "රෞද්‍ර රතු හා කළු වර්ණ සහිත වලස් හිසක් බඳු මහ සොහොන් වෙසක්", "සුදු පැහැති දේව වෙසක්", "පත්තිනි මෑණියන්ගේ සළුවක්", "සරල සුදු සරමක්", "ආතුරයාගේ තැතිගැන්ම දුරු කිරීමට මෙම ප්‍රබල වෙස් ගැන්වීම සිදු කෙරේ."),
        q("උඩරට 'කොහොඹා කංකාරියේදී' ඉදිරිපත් කරන 'යක්කම් පහ' අතරට අයත් අංග දෙකක් නම් කරන්න.", "සීතා යක්කම සහ නයා යක්කම", "සන්නි දහඅට සහ කෝලම", "පොල් කෙළිය සහ රබන් පද", "අලාරිප්පු සහ ජතීස්වරම්", "නාට්‍යමය හා උපහාසාත්මක කතා පුවත් යක්කම් පහ මගින් රඟ දැක්වේ."),
        q("ශාන්තිකර්මයකදී 'කඩතුරාව' ලෙස යොදා ගන්නා රෙද්දෙන් සිදු කරන නාට්‍යමය කාර්යය කුමක්ද?", "රංගනය සඳහා කුතුහලය ඇති කර පූජනීය දර්ශනය හෙළි කිරීම", "වහලයේ ජල කාන්දු වැළැක්වීම", "නැට්ටුවන්ගේ මුහුණ පිස දැමීම", "බෙර වසා තැබීම", "පූජා අවස්ථා විවෘත කිරීමට කඩතුරාව ඉවත් කිරීමේ චාරිත්‍රය වැදගත් වේ."),
        q("දේශීය ශාන්තිකර්මවල 'ආතුරයා' සුවපත් වීමට බෙහෙවින්ම ඉවහල් වන මනෝවිද්‍යාත්මක සාධකය කුමක්ද?", "සාමූහික පවුලේ හා ගමේ සහයෝගය සහ දැඩි විශ්වාසය", "ආතුරයා තනිවම අඳුරු කාමරයක සිර කර තබා ගැනීම", "යාගය පුරා රෝගියාට කිසිදු ආහාරයක් නොදී තැබීම", "බෙර හඬින් හා ඝෝෂාවෙන් රෝගියා බිය ගැන්වීම පමණක්", "සමාජ රැකවරණය හා භක්තිය ආතුරයාට ඉමහත් මානසික ශක්තියක් ලබා දෙයි."),
        q("සබරගමු 'පහන් මඩුවේදී' 'අඹ විදමන' නමැති නාට්‍යමය අංගයෙන් නිරූපණය කරන්නේ කුමන දේව පුවතද?", "පත්තිනි දේවිය අඹ ගෙඩියකින් උපන් කථා පුවත", "සමන් දෙවියන් සමනොළට වැඩම කළ පුවත", "මලය රජු ලක්දිවට ආ පුවත", "දෙවොල් දෙවියන් මුහුද තරණය කළ පුවත", "සක් දෙවිඳු හීයකින් විද අඹය නෙළා පත්තිනි උපත සිදු වූ අයුරු මෙහි රඟ දැක්වේ."),
        q("දේශීය ශාන්තිකර්මවල 'පිදේනි තටු' සකස් කිරීම සඳහා ප්‍රධාන වශයෙන් ගන්නා ස්වාභාවික ද්‍රව්‍ය මොනවාද?", "කෙසෙල් පතුරු, උණ පතුරු සහ ගොක් කොළ", "සිමෙන්ති සහ යකඩ", "ප්ලාස්ටික් තැටි", "වීදුරු කැබලි", "පූජාව අවසන් වූ පසු ස්වාභාවිකව දිරාපත් වන ද්‍රව්‍ය භාවිත කිරීම සම්ප්‍රදායයි."),
        q("පහතරට 'ගම්මඩුව' පැවැත්වෙන කාලය බොහෝ විට සම්බන්ධ වන්නේ කුමන ගැමි කාලසටහනකටද?", "ගොයම් අස්වැන්න නෙළා ගත් පසු දෙවියන්ට කෘතවේදී වීමට", "දැඩි වර්ෂාපතන කාලයේදී පමණක්", "අවමංගල්‍ය කටයුතු අතරතුර", "විභාග සමයේදී", "අස්වනු සශ්‍රීක වූ පසු ගම්මුන් එකට එක්ව දෙවියන්ට ස්තූති පූජා පවත්වති."),
        q("කොහොඹා කංකාරියේදී නැට්ටුවා 'අයිලය' ඉදිරිපිට සිට පවත්වන පූජා නැටුමෙන් අපේක්ෂා කරන්නේ කුමක්ද?", "දෙවියන්ගේ බැල්ම ලබාගෙන රටට හා රජුට සෙත් පැතීම", "වෙස් ඇඳුම අලෙවි කිරීම", "තාලම්පට වෙනස් කිරීම", "ප්‍රේක්ෂකයන් පිට කිරීම", "රාජ්‍ය ආරක්ෂාව හා සමාජ සාමය උදෙසා මෙම දේව පූජාව පැවැත්විණි."),
        q("බලි ශාන්තිකර්මයේදී නව ග්‍රහයන් සඳහා බලි ඇඹීමට 'හුඹස් මැටි' තෝරා ගැනීමට හේතුව කුමක්ද?", "පවිත්‍රතාව, නම්‍යශීලී බව සහ ඉරිතැලීමකින් තොරව අඹා ගැනීමේ හැකියාව", "කිසිදු ලෙසකින් හැඩගැන්විය නොහැකි යකඩ මෙන් තද බව", "ජලය සමඟ කලවම් කළද වතුරේ දිය නොවී ගල් සේ තිබීම", "වර්ණ ගැල්වීමකින් තොරවම ස්වාභාවික රන් පැහැයෙන් දිලිසීම", "වේයන් විසින් සියුම්ව පිරිසිදු කළ හුඹස් මැටි පූජා රූප ඇඹීමට අගනේය."),
        q("දේශීය ශාන්තිකර්මවල 'දුම්මල ගසා ගිනි මැවීම' සඳහා වම් අතේ තබා ගන්නා ආලෝක උපකරණය කුමක්ද?", "කොප්පරා හෝ පිරිසිදු රෙදි පන්දම (විලක්කුව)", "ඉහළින් එල්ලා තැබූ සුදු විදුලි බල්බ පෙළ", "කුඩා පිත්තල පහනක දැල්වූ කෙටි ඉටිපන්දම", "වීදුරු ආවරණයක් සහිත පැරණි භූමිතෙල් ලන්තෑරුම", "පන්දම් දැල්ලට දුම්මල කුඩු විසුරුවා දැවැන්ත ගිනි එළියක් මවයි."),
        q("උඩරට 'වලියක් මංගල්‍යය' ඉදිරිපත් කිරීම සඳහා නැට්ටුවන් තෝරා ගැනෙන්නේ කුමන ශාන්තිකර්ම පරපුරකින්ද?", "කොහොඹා කංකාරිය හා සම්බන්ධ උඩරට පාරම්පරික ශිල්පීන්ගෙන්", "පහතරට සන්නි ශිල්පීන්ගෙන්", "ඉන්දියානු කථක් ශිල්පීන්ගෙන්", "බැලේ ශිල්පීන්ගෙන්", "දළදා මාලිගාවේ හා සිව් මහා දේවාලවල පාරම්පරික රාජකාරි ශිල්පීන් මෙය ඉටු කරයි."),
        q("දේශීය ශාන්තිකර්ම සාහිත්‍යයේදී 'සෙත් කවි' හා 'යාතිකා' ගායනා කිරීමෙන් අරමුණු කරන්නේ කුමක්ද?", "ආතුරයාගේ නිදුක් නිරෝගී භාවය හා දීර්ඝායුෂ ප්‍රාර්ථනා කිරීම", "සතුරු බලවේගවලට එරෙහිව වස් කවි හා ශාප කීම", "මඩු යාගයේ පූජා වට්ටි විස්තර ප්‍රකාශයට පත් කිරීම", "නැට්ටුවන්ගේ වේගවත් පද රටා අතරමග නවතා බාධා කිරීම", "සුභ ගණ හා අක්ෂර සංයෝගයෙන් යහපත් ප්‍රතිඵල ගෙන ඒම සෙත් කවිවල කාර්යයයි."),
        q("පහතරට 'රට යකුම' පැවැත්වෙන විට මඩුවේ එල්ලා තබන 'හත් අඩිය' නමැති සංකේතය කුමක්ද?", "පියවර හතක් නිරූපණය කරන සැරසිලි හා ආශිර්වාද අංගයකි", "සන්නි යකුන් නිරූපණය කරන දැව වෙස්මුහුණු හතකි", "ශාන්තිකර්ම මඩුව වටා වාදනය කරන යක් බෙර හතකි", "ලී කෙළි නැටුම සඳහා සකසා තබන සවිමත් කෝටු හතකි", "දරු උපත හා ආරක්ෂාව සමඟ බැඳුණු පුරාණ චාරිත්‍ර අංගයක් ලෙස හත් අඩිය සැලකේ."),
        q("ශාන්තිකර්මයකදී 'කළස් තැබීම' හෙවත් පුන්කලසක් පූජා ආසනය අසල තැබීමෙන් ප්‍රකට වන්නේ කුමක්ද?", "පූර්ණ සශ්‍රීකත්වය, ශුභ නිමිත්ත හා පිරිසිදු බව", "වතුර ඉසීමේ අවශ්‍යතාව පමණි", "රංගනයේ අවසානය", "බෙර තෙත් කිරීම", "පොල් මලක් දැමූ පුන්කලස සෑම සිංහල ශුභ කටයුත්තකම අනිවාර්ය සංකේතයකි."),
        q("දේශීය ශාන්තිකර්මවලදී භාවිත වන 'මන්ත්‍ර' වලින් ප්‍රධාන වශයෙන් ඉල්ලා සිටින්නේ කුමන අවසරයද?", "බුද්ධ, ධම්ම, සංඝ යන ත්‍රිවිධ රත්නයේ බලයෙන් අමනුෂ්‍ය දෝෂ පහව යාම", "විදේශීය නර්තන සම්ප්‍රදායන් මඩුවට එක් කිරීමේ අවසරය", "ශාන්තිකර්මය සඳහා නව බෙර හා වෙස්මුහුණු තැනීමේ අවසරය", "දේව දානය හා මුරුතැන් පූජාව පිස බෙදා දීමේ අවසරය පමණි", "සියලු ශාන්තිකර්ම මන්ත්‍ර හා තෙල් පූජාවන් බෞද්ධ පසුබිම මත පදනම් වේ."),
        q("පහතරට 'දහඅට සන්නියේ' එන 'බිහිරි සන්නිය' නිරූපණය කරන්නේ කුමන රෝගී තත්ත්වයද?", "කන් ඇසීමේ දුර්වලතාව හා කන් රෝග", "ඇස් පෙනීමේ දුර්වලතාව", "උණ ගැනීම", "පාද කැඩීම", "එක් එක් සන්නි යකා රෝගියාගේ විශේෂිත රෝග ලක්ෂණ හාස්‍යජනකව පෙන්වයි."),
        q("දහඅට සන්නියේ 'කණ සන්නිය' වේදිකාවට පැමිණි විට පිළිබිඹු කරන්නේ කුමන රෝගයක්ද?", "ඇස් පෙනීමේ දුර්වලතා හා අක්ෂි රෝග", "කථන ආබාධ", "කන් ඇසීමේ රෝග", "හිසරදය", "සන්නි යකුන්ගේ වෙස්මුහුණ හා ඉරියව් මගින් අදාළ රෝගය පැහැදිලිව හඳුනාගත හැකිය."),
        q("ශාන්තිකර්මයක 'කුල දෙවියන්' පිදීම යනුවෙන් අදහස් කරන්නේ කවුරුන්ද?", "ප්‍රදේශයේ ආරක්ෂාව භාර ප්‍රාදේශීය දේවතාවුන්ට පූජා දැක්වීම", "විදේශීය දේව කතා වල එන රජවරුන් හා චරිත පිදීම", "යාගය ඉදිරිපත් කරන නැටුම් ශිල්පීන්ට තුති පඬුරු දීම", "ප්‍රදේශයේ ජන නාට්‍ය කණ්ඩායම්වලට පූජා ආහාර දීම", "ගමේ හා ප්‍රදේශයේ බණ්ඩාර දෙවිවරුන් ඇතුළු ආරක්ෂක දෙවිවරුන් පිදීම සිරිතකි."),
        q("කොහොඹා කංකාරියේදී 'මඟුල් බෙර' වාදනයෙන් පසුව නැට්ටුවන් අතැතිව නටන 'තානම්' නොවන අංගය කුමක්ද?", "යක් ඇනුම", "තෙල්මේ පාලිය", "වඩිග පටුන", "දහඅට සන්නිය", "උඩරට වෙස් නැට්ටුවන්ගේ ප්‍රතාපවත් නර්තන අංගයක් ලෙස යක් ඇනුම සැලකේ."),
        q("ශාන්තිකර්ම මඩුවේදී 'සභාව' හෙවත් රැස්ව සිටින පිරිසට යකැදුරා දක්වන ගෞරවය කුමක්ද?", "තෙරුවන්ට, දෙවියන්ට, ගුරුවරුන්ට හා සභාවට වැඳ අවසර ගැනීම", "ප්‍රේක්ෂකයන් නොසලකා හැරීම", "බෙර වාදනය නතර කර ඉවත් වීම", "වේදිකාවේ තිරය වසා දැමීම", "සභා ගෞරවය දේශීය ශාන්තිකර්ම සම්ප්‍රදායේ උතුම් සදාචාර ලක්ෂණයකි."),
        q("පහතරට 'සූනියම් කැපිල්ලේදී' සූනියම් යකා හෙවත් ඕඩ්ඩි කුමාරයාගේ රංගනයේදී දැකිය හැකි වෙස් ස්වභාවය කුමක්ද?", "නාග පෙන රැසක් හිස මත හා ශරීරය වටා ඇති බිහිසුණු වෙසක්", "මොනර පිහාටු සහිත හිස්වැසුමක්", "සුදු ජටාවක්", "ළමා ඇඳුමක්", "ඕඩ්ඩි කුමාරයා නාගාභරණවලින් සැරසී සිටින බව යාග සාහිත්‍යයේ කියැවේ."),
        q("බලි ශාන්තිකර්මයේදී බලි රූපය වර්ණ ගැන්වීමට ගන්නා සුදු පැහැති ස්වාභාවික මැටි වර්ගය කුමක්ද?", "මකුළු මැටි (කිරිමැටි)", "කළු දැලි කුඩු", "කහ අල යුෂ", "නිල් අවරි පොතු", "ගමේ පරිසරයෙන් සොයා ගන්නා මකුළු මැටි සුදු වර්ණකය ලෙස භාවිත කෙරේ."),
        q("දේශීය ශාන්තිකර්මවල 'සමයම්' යන පදයෙන් හඳුන්වනු ලබන්නේ කුමන කාල පරිච්ඡේදයන්ද?", "සන්ධ්‍යා, මධ්‍යම රාත්‍රී සහ අලුයම යන යාග කාල කොටස් තුන", "යාගයට පෙර සූදානම් වන මාස තුනක පේවීමේ කාලයක්", "ශාන්තිකර්මයෙන් පසු ගමට ලැබෙන දින තුනක නිවාඩුවක්", "වසරකට වරක් පමණක් පවත්වන දීර්ඝ උත්සව කාලයක්", "සන්ධ්‍යා සමයම, මැදියම් සමයම හා අලුයම් සමයම ලෙස යාගය කාල තුනකට බෙදේ."),
        q("සබරගමු 'පහන් මඩුව' හා පහතරට 'දෙවොල් මඩුව' යන දෙකෙහිම පොදු වශයෙන් පිදුම් ලබන දෙවඟන කවුද?", "පත්තිනි දේවිය", "සරස්වතී දේවිය පමණි", "ලක්ෂ්මී දේවිය පමණි", "කාලි දේවිය පමණි", "රෝග නිවාරණය, අස්වනු ආරක්ෂාව හා පතිවත රැකීම උදෙසා පත්තිනි මෑණියන් පුදනු ලැබේ."),
        q("දේශීය ශාන්තිකර්මයක 'තොරණ' ඉදි කිරීමේදී මැද කොටසේ රඳවන දේව සංකේතය හෝ ආභරණය කුමක්ද?", "දේව ආයුධ, පත්තිනි සළඹ හෝ දේව පිළිම", "ලී කෝටු", "මැටි කළගෙඩි", "පොල් කටු", "මඩුවේ මධ්‍ය ලක්ෂ්‍යය ලෙස පූජා ආසනය හා තොරණ ගෞරවයෙන් සලකයි."),
        q("කොහොඹා කංකාරියේදී 'ගුරුගේ මාලාව' නටන නැට්ටුවන් පිරිස බොහෝ විට නටන්නේ කුමන ආකාරයකින්ද?", "වෙස් නැට්ටුවන් පෙළට හා රවුමට සිට ගැටබෙර තාලයට", "තනිවම බිම ඉඳගෙන", "වෙස්මුහුණු පැළඳගෙන", "සංගීතය නොමැතිව", "සමූහ වෙස් නැටුමේ ප්‍රතාපවත් බව කංකාරිය තුළදී ඉස්මතු වේ."),
        q("ශාන්තිකර්මයකදී 'කළස් පාලිය' ඉදිරිපත් කිරීමෙන් සංකේතවත් වන යහපත් අදහස කුමක්ද?", "සියලු අපිරිසිදු දෑ සෝදා හැර සෞභාග්‍යය ළඟා කර දීම", "මඩුවේ බිම තෙත් කිරීම", "බෙර වාදනය නතර කිරීම", "කළගෙඩි බිඳ දැමීම", "ජලය පිරුණු කළයකින් ආශිර්වාද ගෙන ඒම මෙම පාලියෙන් පෙන්වයි."),
        q("පහතරට 'රට යකුම' පැවැත්වීමේදී දොළහ පාලියට අයත් තවත් ප්‍රසිද්ධ පාලි අංගයක් නම් කරන්න.", "අංගම් පාලිය හෝ පන්දම් පාලිය", "ගොයම් පාලිය", "කළගෙඩි පාලිය", "රබන් පාලිය", "සන්නි හා රට යකුම තුළ පවිත්‍ර කිරීමේ පාලි නැටුම් පිළිවෙළින් නැටවේ."),
        q("දේශීය ශාන්තිකර්මයක 'ආශිර්වාදය' අවසානයේදී ගමේ සියලුම සතුන්ට හා ගොවි බිම්වලට සෙත් පැතීමෙන් පෙනෙන්නේ කුමක්ද?", "පරිසරය හා සියලු ජීවීන් කෙරෙහි ඇති සාමූහික කරුණාව හා ගෞරවය", "ප්‍රධාන ආතුරයාට පමණක් සීමා වූ ආශිර්වාදයක් ප්‍රාර්ථනා කිරීම", "ගොවි බිම්වලට හානි කරන වන සතුන් විනාශ වේවායි පැතීම", "යාගයේ සාර්ථකත්වයෙන් පෞද්ගලික ලාභ ප්‍රයෝජන පමණක් පැතීම", "බෞද්ධ මෛත්‍රී සංකල්පය දේශීය ශාන්තිකර්ම තුළ මැනවින් මුසු වී තිබේ."),
        q("බලි යාගයේදී 'පංච වර්ණ' සකස් කිරීම සඳහා කළු පැහැය ලබාගන්නා ස්වාභාවික මාධ්‍යය කුමක්ද?", "දැලි, අඟුරු හෝ කළු මැදිරිය පොතු", "කෘත්‍රිම තෙල් තීන්ත පමණි", "සුදු මකුළු මැටි", "කහ කුඩු", "ගැමි පරිසරයෙන් පහසුවෙන් ලැබෙන ද්‍රව්‍ය යොදා ස්වාභාවික වර්ණ තනා ගනී."),
        q("ශාන්තිකර්ම මඩුවේ 'මගුල් තොරණ' ඉදිරියේ තබන 'හත් මාළුව' වැනි ආහාර පූජා සඳහා විශේෂත්වයක් දෙන්නේ ඇයි?", "ස්වාභාවික හා නැවුම් භෝගවල සාරය දෙවියන්ට පිදීමට", "ආහාර නාස්ති කිරීමට", "නැට්ටුවන්ගේ වේගය අඩු කිරීමට", "මඩුව අපිරිසිදු කිරීමට", "සරුසාර අස්වැන්නේ පළමු කොටස දෙවියන්ට කැප කිරීම ගැමි කෘතවේදීත්වයයි."),
        q("උඩරට 'කොහොඹා කංකාරිය' සහ 'වලියක් මංගල්‍යය' යන දෙකම සිදු කරන්නේ කුමන ශාන්තිකර්ම ගණය යටතේද?", "දේව ශාන්තිකර්ම ගණය යටතේ", "යක්ෂ ශාන්තිකර්ම ගණය යටතේ", "ග්‍රහ ශාන්තිකර්ම ගණය යටතේ", "විදේශීය ශාන්තිකර්ම ගණය යටතේ", "මෙම දෙකම දේව ආශිර්වාදය පතා පවත්වන උඩරට උසස් පූජා විධි වේ."),
        q("ශාන්තිකර්මයකදී 'සීනු නාදය' හා 'හක්ගෙඩි නාදය' වැදගත් වන්නේ කුමන අවස්ථාවලදීද?", "දේව ආරාධනා, පූජා ඔප්පු කිරීම හා ආශිර්වාද අවස්ථාවලදී", "නැටුම මැද විවේක ගැනීමට", "ප්‍රේක්ෂකයන් පිටව යාමට", "බෙර සම ගැලවීමට", "මංගල ශබ්ද පූජාව ශාන්තිකර්මයේ ගාම්භීරත්වය තීව්‍ර කරයි."),
        q("පහතරට 'දහඅට සන්නියේදී' සන්නි යකුන් අවසානයේ පිදේනි පිළිගෙන කරන පොරොන්දුව කුමක්ද?", "ආතුරයාගේ රෝග හා දෝෂ අතහැර නැවත හානි නොකර පිටව යාම", "ආතුරයා සමඟ නැවතී සිටීම", "මඩුව කඩා දැමීම", "බෙර වාදකයා රැගෙන යාම", "රෝගියාගේ සිතේ රෝග බිය සම්පූර්ණයෙන් නිදහස් කිරීම මෙම නාටකීය පොරොන්දුවෙන් සිදු වේ."),
        q("ශාන්තිකර්මයකදී 'දෙහි කැපීම' සිදු කරන්නේ ආතුරයාගේ ශරීරයේ කුමන ස්ථාන ස්පර්ශ කරමින්ද?", "හිස මුදුනේ සිට පාද දක්වා අනුපිළිවෙළින්", "අත්ල පමණක්", "පිටුපස පමණක්", "පාවහන් මත පමණක්", "හිසේ සිට දෙපතුල දක්වා ඇස්වහ කටවහ ඉවත් වන බව විශ්වාස කරමින් දෙහි කපයි."),
        q("දේශීය ශාන්තිකර්ම හා යාතුකර්ම අධ්‍යයනය කිරීමෙන් සිසුන් තුළ වර්ධනය වන වැදගත්ම ආකල්පය කුමක්ද?", "සාම්ප්‍රදායික ගැමි වෛද්‍ය විද්‍යාව, කලාව හා සමාජ එකමුතුව අගය කිරීම", "සෙසු සංස්කෘතීන් ප්‍රතික්ෂේප කිරීම", "වැරදි මිථ්‍යාවන්ට රැවටීම", "නර්තනය අත්හැරීම", "ශාන්තිකර්ම යනු ජන කලාව, සාහිත්‍යය හා මනෝ චිකිත්සාව එක් වූ උසස් උරුමයකි."),
        q("O/L නර්තන විෂය මාලාවට 'ශාන්තිකර්ම' ඇතුළත් කර තිබීමේ ප්‍රධානතම අධ්‍යාපනික අරමුණ කුමක්ද?", "දේශීය නර්තන සම්ප්‍රදායන් බිහි වූ මූලික රංග භූමිය හා සංස්කෘතික පසුබිම හඳුනා ගැනීම", "සියලුම සිසුන් ප්‍රායෝගික යකැදුරන් බවට පත් කිරීම පමණි", "වෙනත් සෞන්දර්ය හා ශාස්ත්‍රීය විෂයන් අමතක කර දැමීම", "ශාන්තිකර්ම සඳහා සාම්ප්‍රදායික බෙර භාවිතය අඩු කර ගැනීම", "සිංහල නර්තන කලාවේ පෝෂණ මූලාශ්‍රය වූ ශාන්තිකර්ම පිළිබඳ නිවැරදි අවබෝධයක් ලබා දීම මෙහි අරමුණයි.")
    )
}

